#include "tigersheets/main_window.hpp"
#include "tigersheets/grid.hpp"
#include <QApplication>
#include <QDialog>
#include <QLineEdit>
#include <QPushButton>
#include <QTabWidget>
#include <QTableView>
#include <QTemporaryDir>
#include <QTimer>
#include <QTest>
#include <QCheckBox>
#include <QComboBox>
#include <QTableWidget>
#include <QTabBar>
#include <iostream>
#include <stdexcept>
using namespace tigersheets;
namespace {
void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
void blankNativeFind(){
 MainWindow window;window.show();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");require(grid->model()->setData(grid->model()->index(35,3),"1453",Qt::EditRole),"seed the source-video copied statement value");grid->setCurrentIndex(grid->model()->index(36,3));const QItemSelection selection(grid->model()->index(35,3),grid->model()->index(37,3));grid->selectionModel()->select(selection,QItemSelectionModel::ClearAndSelect);require(window.executeCommand("copy"),"retain a copied source rectangle before accidental Find");const auto before=window.currentSession().snapshot();bool native=false;
 QTimer::singleShot(0,&window,[&]{if(auto* dialog=window.findChild<QDialog*>("findReplace.dialog")){auto* tabs=dialog->findChild<QTabWidget*>("findReplace.tabs");auto* input=dialog->findChild<QLineEdit*>("findReplace.findWhat");native=dialog->windowTitle()=="Find and Replace"&&tabs&&tabs->count()==2&&tabs->tabText(0)=="Find"&&tabs->tabText(1)=="Replace"&&tabs->currentIndex()==0&&input&&input->text().isEmpty()&&dialog->findChild<QPushButton*>("findReplace.options")&&dialog->findChild<QPushButton*>("findReplace.findAll")&&dialog->findChild<QPushButton*>("findReplace.findNext")&&dialog->findChild<QPushButton*>("findReplace.close");if(qEnvironmentVariableIsSet("TIGERSHEETS_FIND_CAPTURE"))dialog->grab().save(QString::fromLocal8Bit(qgetenv("TIGERSHEETS_FIND_CAPTURE")));QTest::keyClick(dialog,Qt::Key_Escape);}else if(auto* old=qobject_cast<QDialog*>(QApplication::activeModalWidget()))old->reject();});grid->setFocus();QTest::keyClick(grid,Qt::Key_F,Qt::ControlModifier);QApplication::processEvents();require(native,"Ctrl+F opens the source's blank native Find and Replace dialog with Find/Replace tabs and Options, Find All, Find Next and Close controls");require(window.currentSession().snapshot()==before&&grid->selectionModel()->selection()==selection,"dismissing accidental blank Find preserves all data, history and the copied selection");auto* outline=grid->viewport()->findChild<QWidget*>("worksheet.copyBorder");require(outline&&outline->isVisible(),"closing Find preserves the source's marching-ants copy state");
}
void functionalSparseFind(){
 MainWindow window;window.show();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());require(model->setData(model->index(0,0),"Revenue",Qt::EditRole)&&model->setData(model->index(1,1),"revenue",Qt::EditRole)&&model->setData(model->index(999999,12),"Revenue forecast",Qt::EditRole)&&model->setData(model->index(9,1),"=6*7",Qt::EditRole),"seed sparse Find values including a distant authored row and a formula");window.recalculateNow();grid->setCurrentIndex(model->index(0,0));grid->selectionModel()->select(QItemSelection(grid->currentIndex(),grid->currentIndex()),QItemSelectionModel::ClearAndSelect);const auto before=window.currentSession().snapshot();require(window.executeCommand("find"),"show native Find");auto* dialog=window.findChild<QDialog*>("findReplace.dialog");auto* input=dialog->findChild<QLineEdit*>("findReplace.findWhat");auto* next=dialog->findChild<QPushButton*>("findReplace.findNext");QTest::keyClicks(input,"revenue");next->click();require(grid->currentIndex()==model->index(1,1),"Find Next searches stored cells after the current cell in row order");QTest::keyClick(input,Qt::Key_Return);require(grid->currentIndex()==model->index(999999,12),"Enter repeats sparse Find without scanning a million empty rows");next->click();require(grid->currentIndex()==model->index(0,0),"Find Next wraps to the first matching cell");
 dialog->findChild<QPushButton*>("findReplace.options")->click();auto* matchCase=dialog->findChild<QCheckBox*>("findReplace.matchCase");auto* entire=dialog->findChild<QCheckBox*>("findReplace.entireCell");auto* lookIn=dialog->findChild<QComboBox*>("findReplace.lookIn");require(matchCase&&entire&&lookIn&&matchCase->isVisible(),"Options expands native matching, scope, order and Look in controls");input->setText("Revenue");matchCase->setChecked(true);next->click();require(grid->currentIndex()==model->index(999999,12),"Match case excludes lowercase source text");entire->setChecked(true);next->click();require(grid->currentIndex()==model->index(0,0),"Match entire cell excludes a longer forecast label");matchCase->setChecked(false);entire->setChecked(false);input->setText("42");lookIn->setCurrentText("Values");next->click();require(grid->currentIndex()==model->index(9,1),"Look in Values finds a calculated formula result");lookIn->setCurrentText("Formulas");input->setText("Rev?nue*");dialog->findChild<QPushButton*>("findReplace.findAll")->click();auto* results=dialog->findChild<QTableWidget*>("findReplace.results");require(results&&results->isVisible()&&results->rowCount()==3,"Find All lists wildcard matches across sparse stored values");require(window.currentSession().snapshot()==before,"searching, options, navigation and Find All never edit workbook data or history");dialog->reject();
}
void functionalReplace(){
 MainWindow window;window.show();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());require(model->setData(model->index(0,0),"Revenue",Qt::EditRole)&&model->setData(model->index(0,1),"revenue forecast",Qt::EditRole),"seed two case-insensitive replacement matches");require(model->apply(Json::array({{{"type","set_style"},{"sheet",model->sheetId().toStdString()},{"row",1},{"col",2},{"style",{{"bold",true},{"fill","#123456"}}}}})),"retain source formatting during text replacement");require(window.executeCommand("sheet.add"),"add a second source sheet for workbook-scope replacement");const auto other=model->sheetId();require(model->setData(model->index(0,0),"Revenue",Qt::EditRole),"seed a second worksheet match");window.findChild<QTabBar*>("workspace.sheets")->setCurrentIndex(0);grid->setCurrentIndex(model->index(0,0));grid->selectionModel()->select(QItemSelection(grid->currentIndex(),grid->currentIndex()),QItemSelectionModel::ClearAndSelect);const auto before=window.currentSession().snapshot();grid->setFocus();QTest::keyClick(grid,Qt::Key_H,Qt::ControlModifier);QApplication::processEvents();auto* dialog=window.findChild<QDialog*>("findReplace.dialog");require(dialog&&dialog->isVisible()&&dialog->findChild<QTabWidget*>("findReplace.tabs")->currentIndex()==1,"Ctrl+H opens the real Replace tab");auto* input=dialog->findChild<QLineEdit*>("findReplace.replaceFindWhat");auto* replacement=dialog->findChild<QLineEdit*>("findReplace.replaceWith");auto* all=dialog->findChild<QPushButton*>("findReplace.replaceAll");auto* replace=dialog->findChild<QPushButton*>("findReplace.replace");require(input&&replacement&&all&&replace,"Replace tab provides Find what, Replace with, Replace All and Replace");input->setText("revenue");replacement->setText("Sales");dialog->findChild<QPushButton*>("findReplace.replaceOptions")->click();dialog->findChild<QComboBox*>("findReplace.within")->setCurrentText("Workbook");all->click();require(model->raw(0,0)=="Sales"&&model->raw(0,1)=="Sales forecast"&&model->cellStyle(0,1).at("bold")==true,"Replace All updates sparse matches while preserving cell styles");bool replacedOther=false;for(const auto& sheet:window.currentSession().snapshotView().at("sheets"))if(sheet.at("id")==other.toStdString())replacedOther=sheet.at("cells")[0].at("input")=="Sales";require(replacedOther,"Workbook-scope Replace All includes other worksheets");require(window.executeCommand("undo")&&window.currentSession().snapshotView().at("sheets")==before.at("sheets"),"one Undo restores every replacement across the workbook");replace->click();require(model->raw(0,0)=="Sales"&&model->raw(0,1)=="revenue forecast"&&grid->currentIndex()==model->index(0,1),"Replace changes the current matching cell and selects the next match");const auto replaced=window.currentSession().snapshot();QTest::keyClick(dialog,Qt::Key_Escape);require(window.currentSession().snapshot()==replaced,"Escape closes Replace without another workbook mutation");
}
void reopeningUsesCurrentSelection(){
 MainWindow window;window.show();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());require(model->setData(model->index(0,0),"Revenue",Qt::EditRole)&&model->setData(model->index(0,1),"Other",Qt::EditRole),"seed separate original and replacement search scopes");grid->selectionModel()->select(QItemSelection(model->index(0,1),model->index(1,1)),QItemSelectionModel::ClearAndSelect);require(window.executeCommand("find"),"open Find on the original selected range");auto* dialog=window.findChild<QDialog*>("findReplace.dialog");dialog->reject();grid->setCurrentIndex(model->index(2,0));grid->selectionModel()->select(QItemSelection(grid->currentIndex(),grid->currentIndex()),QItemSelectionModel::ClearAndSelect);require(window.executeCommand("find"),"reopen native Find after selecting a different cell");dialog->findChild<QLineEdit*>("findReplace.findWhat")->setText("Revenue");dialog->findChild<QPushButton*>("findReplace.findNext")->click();require(grid->currentIndex()==model->index(0,0),"reopened Find uses the current selection rather than a stale earlier multi-cell scope");dialog->reject();
}
}
int main(int argc,char** argv){QApplication app(argc,argv);QTemporaryDir state;qputenv("TIGERSHEETS_STATE_DIR",state.path().toUtf8());try{blankNativeFind();if(argc>1&&std::string(argv[1])=="functional")functionalSparseFind();if(argc>1&&std::string(argv[1])=="replace")functionalReplace();if(argc>1&&std::string(argv[1])=="lifecycle")reopeningUsesCurrentSelection();std::cout<<"Native Find and Replace UI passed\n";}catch(const std::exception& error){std::cerr<<"FAILED: "<<error.what()<<'\n';return 1;}}
